"""End-to-end tests of the commands against a temporary Wireshark configuration."""
import pytest

from pcap_labels import cli, wireshark

DEFAULT_RULES = (
    "# DO NOT EDIT THIS FILE!  It was created by Wireshark\n"
    "@Bad TCP@tcp.analysis.flags@[4718,10030,11796][63479,34695,34695]\n"
    "@ARP@arp@[64250,61680,55255][4718,10030,11796]\n"
    "@HTTP@http || tcp.port == 80@[58596,65535,51143][4718,10030,11796]\n"
)
ARP_BACKGROUND = "#faf0d7"
HEADER = "timestamp,src_ip,tcp src_port,dst_ip,ip dst,tcp dst port,udp dst port,protocol,class,\n"
ROWS = (
    " 2023 12:15:58.387265000 Jerusalem Daylight Time,,,,,,,ARP,1,\n"
    " 2023 12:15:58.769286000 Jerusalem Daylight Time,192.0.2.10,,5353,224.0.0.251,,5353,MDNS,1,\n"
    " 2023 12:16:00.000001000 Jerusalem Daylight Time,192.0.2.31,,,192.0.2.32,,,TCP,0,\n"
)


@pytest.fixture
def env(tmp_path, monkeypatch):
    """A fake Wireshark setup: empty personal config plus a global folder with default rules."""
    config, global_dir = tmp_path / "config", tmp_path / "global"
    config.mkdir()
    global_dir.mkdir()
    (global_dir / "colorfilters").write_text(DEFAULT_RULES, encoding="utf-8")
    paths = wireshark.Paths(config, config / "plugins", global_dir)
    monkeypatch.setattr(wireshark, "locate", lambda config_dir=None: paths)
    monkeypatch.setattr(cli, "_interactive", lambda: False)
    csv = tmp_path / "labels.csv"
    csv.write_text(HEADER + ROWS, encoding="utf-8")
    return paths, csv


def rule_lines(paths):
    return [l for l in paths.colorfilters.read_text(encoding="utf-8").splitlines() if l.startswith("@")]


def rule_names(paths):
    return [l.split("@")[1] for l in rule_lines(paths)]


def add(csv, *extra):
    return cli.main(["add", str(csv), "--date", "2023-06-19", *extra])


def test_add_creates_label_rule_and_button(env):
    paths, csv = env
    assert add(csv, "--name", "malicious", "--color", "pink") == 0

    assert paths.plugin_file.exists()                       # plugin installed on first use
    lines = paths.label_file("malicious").read_text(encoding="utf-8").splitlines()
    assert "# name: malicious" in lines and "# date: 2023-06-19" in lines
    assert "1687166158387265\tARP\t\t" in lines
    assert "1687166158769286\tMDNS\t192.0.2.10\t224.0.0.251" in lines

    assert rule_lines(paths)[0] == \
        '@Label: malicious@pcaplabel.name == "malicious"@[65535,26985,46260][0,0,0]'
    assert rule_names(paths)[1:] == ["Bad TCP", "ARP", "HTTP"]   # Wireshark's defaults are kept
    assert paths.buttons.read_text(encoding="utf-8") == (
        '"TRUE","Label: malicious","pcaplabel.name == \\x22malicious\\x22",'
        '"Packets labeled malicious (pcap-labels)"\n')


def test_adding_same_label_again_replaces_it(env):
    paths, csv = env
    add(csv, "--name", "malicious", "--color", "pink")
    assert add(csv, "--name", "malicious", "--color", "green") == 0
    ours = [l for l in rule_lines(paths) if l.startswith("@Label: ")]
    assert len(ours) == 1 and "[20560,51400,25700]" in ours[0]
    assert len(paths.buttons.read_text(encoding="utf-8").splitlines()) == 1
    assert (paths.config_dir / "colorfilters.bak").exists()


def test_two_labels_with_different_colors(env, capsys):
    paths, csv = env
    add(csv, "--name", "malicious", "--color", "pink")
    add(csv, "--name", "scan", "--color", "blue")
    assert rule_names(paths)[:2] == ["Label: scan", "Label: malicious"]
    capsys.readouterr()
    cli.main(["list"])
    out = capsys.readouterr().out
    assert "malicious" in out and "scan" in out and "2023-06-19" in out


def test_color_conflict_without_answer_is_an_error(env, capsys):
    paths, csv = env
    assert add(csv, "--name", "malicious", "--color", ARP_BACKGROUND) == 1
    assert "'ARP'" in capsys.readouterr().err
    assert not paths.label_file("malicious").exists()
    assert not paths.colorfilters.exists()                  # nothing was changed


def test_color_conflict_overwrite_and_add(env):
    paths, csv = env
    assert add(csv, "--name", "a", "--color", ARP_BACKGROUND, "--on-conflict", "add") == 0
    assert rule_names(paths) == ["Label: a", "Bad TCP", "ARP", "HTTP"]
    assert add(csv, "--name", "b", "--color", ARP_BACKGROUND, "--on-conflict", "overwrite") == 0
    assert rule_names(paths) == ["Label: b", "Bad TCP", "HTTP"]   # ARP and label a had that color


def test_color_conflict_interactive_change_color(env, monkeypatch):
    paths, csv = env
    monkeypatch.setattr(cli, "_interactive", lambda: True)
    answers = iter(["c", "not-a-color", "purple"])
    monkeypatch.setattr("builtins.input", lambda prompt="": next(answers))
    assert add(csv, "--name", "malicious", "--color", ARP_BACKGROUND) == 0
    assert "[41120,23130,56540]" in rule_lines(paths)[0]
    assert len(rule_lines(paths)) == 4


def test_by_class_makes_one_label_per_value(env):
    paths, csv = env
    assert add(csv, "--name", "traffic", "--color", "green,red", "--by-class") == 0
    assert paths.label_file("traffic-0").exists() and paths.label_file("traffic-1").exists()
    marks = [l for l in paths.label_file("traffic-1").read_text(encoding="utf-8").splitlines()
             if not l.startswith("#")]
    assert len(marks) == 2
    assert add(csv, "--name", "traffic", "--color", "green", "--by-class") == 1   # one color, two classes


def test_missing_date_guessed_only_with_confirmation(env, monkeypatch, tmp_path):
    paths, _ = env
    day_dir = tmp_path / "06_19"
    day_dir.mkdir()
    csv = day_dir / "labels.csv"
    csv.write_text(HEADER + ROWS, encoding="utf-8")
    assert cli.main(["add", str(csv), "--name", "m", "--color", "pink"]) == 1   # not interactive
    monkeypatch.setattr(cli, "_interactive", lambda: True)
    monkeypatch.setattr("builtins.input", lambda prompt="": "y")
    assert cli.main(["add", str(csv), "--name", "m", "--color", "pink"]) == 0
    assert "# date: 2023-06-19" in paths.label_file("m").read_text(encoding="utf-8")


def test_remove_leaves_other_labels(env):
    paths, csv = env
    add(csv, "--name", "malicious", "--color", "pink")
    add(csv, "--name", "scan", "--color", "blue")
    assert cli.main(["remove", "malicious"]) == 0
    assert not paths.label_file("malicious").exists() and paths.label_file("scan").exists()
    assert rule_names(paths) == ["Label: scan", "Bad TCP", "ARP", "HTTP"]
    buttons = paths.buttons.read_text(encoding="utf-8")
    assert "Label: scan" in buttons and "Label: malicious" not in buttons
    assert cli.main(["remove", "nope"]) == 1


def test_uninstall_removes_plugin_labels_rules_and_buttons(env):
    paths, csv = env
    assert cli.main(["install"]) == 0
    assert paths.plugin_file.exists()
    add(csv, "--name", "malicious", "--color", "pink")
    assert cli.main(["uninstall", "--yes"]) == 0
    assert not paths.plugin_file.exists() and not paths.data_dir.exists()
    assert rule_names(paths) == ["Bad TCP", "ARP", "HTTP"]
    assert paths.buttons.read_text(encoding="utf-8") == ""


def test_invalid_label_name(env):
    _, csv = env
    assert add(csv, "--name", 'bad"name', "--color", "pink") == 1


def test_prompt_without_input_is_a_clean_error(env, monkeypatch, capsys):
    _, csv = env
    monkeypatch.setattr(cli, "_interactive", lambda: True)

    def no_input(prompt=""):
        raise EOFError

    monkeypatch.setattr("builtins.input", no_input)
    assert add(csv, "--name", "malicious", "--color", ARP_BACKGROUND) == 1
    assert "No answer" in capsys.readouterr().err


def test_last_puts_label_after_other_labels_but_before_builtin_rules(env):
    paths, csv = env
    add(csv, "--name", "a", "--color", "pink")
    add(csv, "--name", "b", "--color", "blue", "--last")
    assert rule_names(paths) == ["Label: a", "Label: b", "Bad TCP", "ARP", "HTTP"]
    add(csv, "--name", "c", "--color", "green")                 # default: first
    assert rule_names(paths) == ["Label: c", "Label: a", "Label: b", "Bad TCP", "ARP", "HTTP"]
    add(csv, "--name", "c", "--color", "green")                 # update keeps its place
    assert rule_names(paths)[0] == "Label: c"
    add(csv, "--name", "c", "--color", "green", "--last")       # update with --last moves it
    assert rule_names(paths) == ["Label: a", "Label: b", "Label: c", "Bad TCP", "ARP", "HTTP"]


def test_last_with_no_other_labels_still_beats_builtin_rules(env):
    paths, csv = env
    add(csv, "--name", "a", "--color", "pink", "--last")
    assert rule_names(paths) == ["Label: a", "Bad TCP", "ARP", "HTTP"]


def test_short_options(env):
    paths, csv = env
    assert cli.main(["add", str(csv), "-n", "traffic", "-c", "green,red", "-d", "2023-06-19",
                     "-z", "UTC+3", "-b", "-C", "class", "-o", "add", "-l"]) == 0
    assert rule_names(paths)[:2] == ["Label: traffic-0", "Label: traffic-1"]
    assert cli.main(["uninstall", "-y"]) == 0


def test_hint_says_restart_for_new_label_and_reload_for_data_update(env, capsys):
    paths, csv = env
    add(csv, "--name", "malicious", "--color", "pink")
    assert "Restart Wireshark" in capsys.readouterr().out
    add(csv, "--name", "malicious", "--color", "pink")          # same label, same color
    out = capsys.readouterr().out
    assert "Ctrl+R" in out and "Restart Wireshark" not in out
    add(csv, "--name", "malicious", "--color", "green")         # color changed
    assert "Restart Wireshark" in capsys.readouterr().out
